'use strict';
const people=document.querySelector('#people');
const hours=document.querySelector('#hours');
function calculate(){const p=Number(people.value),h=Number(hours.value),total=p*h*20;document.querySelector('#people-value').value=p;document.querySelector('#hours-value').value=h;document.querySelector('#capacity').textContent=total.toLocaleString('fr-CA');document.querySelector('#annual').textContent=(total*12).toLocaleString('fr-CA');}
people.addEventListener('input',calculate);hours.addEventListener('input',calculate);
document.querySelectorAll('[data-service]').forEach(link=>link.addEventListener('click',()=>{document.querySelector('#interest').value=link.dataset.service;}));
document.querySelector('#draft-button').addEventListener('click',()=>{const idea=document.querySelector('#brief').value.trim();document.querySelector('#prepared-brief').value=`Sujet : ${document.querySelector('#interest').value}\n\nCe que nous aimerions améliorer :\n${idea||'Nous aimerions de l’aide pour trouver une possibilité concrète pour notre entreprise.'}\n\nProchaine étape : discuter de notre utilisation actuelle de l’IA, de nos processus et des possibilités pour notre entreprise.`;document.querySelector('#brief-result').hidden=false;document.querySelector('#copy-status').textContent='';document.querySelector('#prepared-brief').focus();});
document.querySelector('#copy-button').addEventListener('click',async()=>{const field=document.querySelector('#prepared-brief');try{await navigator.clipboard.writeText(field.value);document.querySelector('#copy-status').textContent='Copié.';}catch{field.focus();field.select();document.querySelector('#copy-status').textContent='Sélectionnez et copiez le résumé ci-dessus.';}});

const demos={
 invoices:{mark:'FA',title:'Du courriel à la facture.',subtitle:'Un processus relié. Sans copier-coller.',steps:['Lire le document reçu','Extraire et vérifier les données','À vous de vérifier'],action:'Approuver la facture fictive',done:'Facture fictive approuvée',message:'Exemple terminé. Une personne vérifie le tout avant toute écriture comptable.'},
 onboarding:{mark:'RH',title:'Une première journée bien préparée.',subtitle:'Les bonnes tâches, aux bonnes personnes.',steps:['Recueillir les renseignements d’accueil','Préparer la liste de tâches','À vous d’approuver'],action:'Approuver la liste fictive',done:'Liste fictive approuvée',message:'Exemple terminé. Les tâches sont réunies dans un espace partagé.'},
 reporting:{mark:'BI',title:'Des rapports sans la course.',subtitle:'Réunir les données pour mieux comprendre.',steps:['Recueillir les données sources','Préparer le résumé de la semaine','À vous de vérifier'],action:'Vérifier le rapport fictif',done:'Rapport fictif vérifié',message:'Exemple terminé. Votre équipe vérifie le résumé avant de le partager.'}
};
let currentDemo='invoices';
function selectDemo(key){currentDemo=key;const d=demos[key];document.querySelectorAll('[data-demo]').forEach(b=>{const active=b.dataset.demo===key;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});document.querySelector('#demo-panel').setAttribute('aria-labelledby','tab-'+key);document.querySelector('.task-monogram').textContent=d.mark;document.querySelector('#demo-title').textContent=d.title;document.querySelector('#demo-subtitle').textContent=d.subtitle;['a','b','c'].forEach((suffix,i)=>document.querySelector('#demo-step-'+suffix).textContent=d.steps[i]);document.querySelector('#demo-run').textContent=d.action;document.querySelector('#demo-final-icon').textContent='';document.querySelector('#demo-final-icon').classList.remove('complete');document.querySelector('#demo-final-tag').textContent='VOUS';document.querySelector('#demo-status').textContent='Essayez cet exemple. Aucune donnée réelle n’est traitée.';}
document.querySelectorAll('[data-demo]').forEach((button,i,buttons)=>{button.addEventListener('click',()=>selectDemo(button.dataset.demo));button.addEventListener('keydown',e=>{let index;if(e.key==='ArrowRight')index=(i+1)%buttons.length;else if(e.key==='ArrowLeft')index=(i+buttons.length-1)%buttons.length;else if(e.key==='Home')index=0;else if(e.key==='End')index=buttons.length-1;else return;e.preventDefault();selectDemo(buttons[index].dataset.demo);buttons[index].focus();});});
document.querySelector('#demo-run').addEventListener('click',()=>{const d=demos[currentDemo];document.querySelector('#demo-step-c').textContent=d.done;document.querySelector('#demo-final-icon').textContent='✓';document.querySelector('#demo-final-icon').classList.add('complete');document.querySelector('#demo-final-tag').textContent='FAIT';document.querySelector('#demo-status').textContent=d.message;});
